/**
 * platform - 浏览器端平台识别
 *
 * 用于「立即下载」按钮按访客系统自动指向对应安装包。
 * 纯同步实现：Hero 的 href 在首屏渲染时就要确定，不能等异步结果
 *（navigator.userAgentData.getHighEntropyValues(['architecture']) 是异步的）。
 */

/**
 * 识别当前系统与 CPU 架构。
 * @returns {{ os: 'windows'|'macos'|'linux'|'unknown', arch: 'x64'|'arm64'|'unknown' }}
 */
export function detectPlatform() {
  const ua = navigator.userAgent || '';
  const nav = navigator;
  // userAgentData.platform 是标准值（'Windows' | 'macOS' | 'Linux' | 'Android' ...），
  // 比 ua 字符串解析可靠，老浏览器没有这个字段再退回 ua
  const p = (nav.userAgentData && nav.userAgentData.platform) || nav.platform || '';
  const s = `${ua} ${p}`.toLowerCase();

  // ── 操作系统 ──
  let os = 'unknown';
  if (/iphone|ipad|ipod|android/.test(s)) {
    // 移动端没有对应安装包，交给调用方兜底
    os = /android/.test(s) ? 'linux' : 'macos';
  } else if (/win/.test(s)) {
    os = 'windows';
  } else if (/mac os x|macintosh|mac/.test(s)) {
    os = 'macos';
  } else if (/linux|x11|ubuntu|fedora|debian|cros/.test(s)) {
    os = 'linux';
  }

  // ── 架构 ──
  // ARM64 判定：显式出现 arm/aarch64 关键字（Android、Chrome OS、Linux arm）
  let arch = /arm|aarch64/.test(s) ? 'arm64' : 'x64';
  // macOS 的 Apple Silicon 不会在 UA 里写 ARM，但带 Touch Bar 的 Mac 一定有触摸屏，
  // 而 Intel Mac 机型全都没有触摸屏 —— 这是浏览器端区分 Apple Silicon 的通行做法。
  if (os === 'macos' && !/arm|aarch64/.test(s)) {
    arch = (nav.maxTouchPoints || 0) > 1 ? 'arm64' : 'x64';
  }

  return { os, arch };
}

/**
 * 按平台挑选下载地址。
 * @param {Record<string,string>} urls - 形如 { windows, linux, macosAppleSilicon, macosIntel } 的地址表
 * @param {Record<string,string>} [fallback] - 识别失败时的回退地址表，默认用 urls
 * @returns {string}
 */
export function pickDownloadUrl(urls, fallback = urls) {
  const { os, arch } = detectPlatform();

  if (os === 'windows') return urls.windows;
  if (os === 'linux') return urls.linux;
  if (os === 'macos') {
    return arch === 'arm64'
      ? urls.macosAppleSilicon || urls.macosIntel
      : urls.macosIntel || urls.macosAppleSilicon;
  }

  // 识别不出系统（或手机访客）：给一个一定能打开的地址，别让按钮失效
  return fallback.windows || Object.values(urls)[0];
}

/** 给「立即下载」按钮用的平台中文名 */
export function platformLabel(urls = {}) {
  const { os, arch } = detectPlatform();
  if (os === 'windows') return 'Windows';
  if (os === 'linux') return 'Linux';
  if (os === 'macos') return arch === 'arm64' ? 'macOS Apple' : 'macOS Intel';
  return '下载';
}
